An operator is a method
project/pvector.hpp: assign() and operator= do the same thing, only the name changes.


  // since assign operator returns pvector objects by reference:
  // Note this method changes data of object hence it is *not* declared "const"
  pvector& assign( const pvector& P1)
    {
      for (int i=0; i &lt; NT; i++)
        v[i] = P1.v[i];
      return (*this);
    }

  pvector& operator=(const pvector& V2)
    {
      for (int i=0; i &lt; NT; i++)
        v[i] = V2.v[i];
      return (*this);

    }

The compiler translates every operator into a call of a method of the left operand (*this inside the method), with the right operand as argument:
A = B;          // A.operator=(B);                like A.assign(B);
A = B = C;      // A.operator=(B.operator=(C));   like A.assign(B.assign(C));
C = A + B;      // C.operator=(A.operator+(B));
D += B;         // D.operator+=(B);
s = A*B;        // s = A.operator*(B);
D = A*2.0;      // D = A.operator*(2.0);
if (A == B)     // if (A.operator==(B))
The long forms compile too: try A.assign(B);, A.operator=(C);, D = A.operator+(B);.

Example N6: mydynvec.hpp
examples/N6_a_dynamic_class/mydynvec.hpp


#include&lt;cstdlib&gt;
#include&lt;iostream&gt;
#include&lt;stdio.h&gt;
class myvec
{
  // private members
  int *v; // pointer to array
  int len; // allocated int
public:
  // constructor
  myvec()
    {
      len=0;
      v=nullptr;
    }
  // destructor
  ~myvec()
    {
      if (v!=nullptr)
        delete[] v;
    }

  // allocate memory for array
  void alloc(int l) 
    {
      len=l;
      v = new int[len];// new double[]
    }

  // assign value to (i+1)-th element of the array
  void set(int i, int val)
    {
      v[i] = val;
    }
  // get (i+1)-th element of array
  // a=V(i);
  // V(i) = 2.0;
  int get(int i) const // (*this) is passed implicitly, with the const modifier
    {
      return v[i];
    }
  // get actual length of array
  int length(void) const
    {
      return len;
    }
  // resize array (enlarge)
  void resize(int l)
    {
      int *vt;
      vt = new int[l];
      // initialize with all elements and 0 if larger
      for (int i=0; i &lt; l; i++)
        vt[i] = (i &lt; len)?v[i]:0.0;
      len = l;
      if (v!=nullptr)
        delete [] v;
      v=vt;
    }
 };

