  C = rint(K);       std::cout &lt;&lt; "rint(K)=" &lt;&lt; C &lt;&lt; "\n";
  C = mulcw(A, B);   std::cout &lt;&lt; "mulcw(A,B)=" &lt;&lt; C &lt;&lt; "\n";
  C = divcw(A, B);   std::cout &lt;&lt; "divcw(A,B)=" &lt;&lt; C &lt;&lt; "\n";
