Example N8: genvec.hpp
examples/N8_generic_programming/genvec.hpp


#include&lt;cstdlib&gt;
#include&lt;iostream&gt;
// a generic class (a metaclass or class template)
// ntype can be float, double, long double, ...
constexpr int NT=3;// &lt;---- like #define

template &lt;typename ntype&gt;
class genvec
{
  // private members
  ntype v[NT];

public:

  void set(int i, ntype val)
    {
      v[i] = val;
    }

   ntype get(int i) const
    { 
      return v[i];
    }

  void show(void) const
    {
      std::cout &lt;&lt; "(";
      for (int i = 0; i &lt; NT; i++) 
        {
          std::cout &lt;&lt; get(i);
          if (i &lt; NT-1)
            std::cout &lt;&lt; ",";
          else
            std::cout &lt;&lt; ")\n";
        }
    }
  genvec()
    {
    }

  ~genvec()
    {
    }
};


template &lt;typename ntype&gt; (line 7): genvec is a class template, a recipe for classes. Inside it ntype is a type still to be chosen; the rest is an ordinary class.
constexpr int NT=3; (line 5) is a typed constant known when compiling: it can size the array v, like the macro of Lab #1, but it is a real variable with a type and a scope.

